from pathlib import Path
root=Path('.')

def rw(rel, old, new):
    p=root/rel; s=p.read_text(encoding='utf-8')
    if old not in s:
        raise SystemExit(f'pattern missing in {rel}: {old[:100]}')
    p.write_text(s.replace(old,new,1),encoding='utf-8')

